// Love page - minimal function (replaces packed love.min.js)
// Removed: discontinued Baidu Share API

(function($) {
  // Music play/pause toggle
  var audio = document.getElementById('bgmMusic');
  $('#on').click(function() {
    audio.pause();
    $(this).hide();
    $('#off').show();
  });
  $('#off').click(function() {
    audio.play();
    $(this).hide();
    $('#on').show();
  });

  // Progress bar update
  function updateProgress() {
    if (audio && audio.duration) {
      var pct = (audio.currentTime / audio.duration) * 100;
      $('.progress').css('width', pct + '%');
    }
  }
  if (audio) {
    audio.addEventListener('timeupdate', updateProgress);
  }

  // Loading state
  $('.nojavascript').hide();

  // Hide loading on flowtime ready
  if (typeof Flowtime !== 'undefined') {
    Flowtime.showProgress();
  }

})(jQuery);
